mapper.update:
update raffle_activity_stage
set state = #{state}, update_time = now()
where activity_id = #{activityId}
  and channel = #{channel}
  and source = #{source}

mapper.select:
select id, channel, source, activity_id, state, create_time, update_time
from raffle_activity_stage
where activity_id = #{activityId}
  and channel = #{channel}
  and source = #{source}
order by id desc
limit 1

select id, channel, source, activity_id, state, create_time, update_time
from raffle_activity_stage
where channel = #{channel}
  and source = #{source}
  and state = 'active'
order by id desc
